exercises.solution:
// Ustawianie innerHTML danymi od uzytkownika jest ryzykowne, poniewaz
// przegladarka INTERPRETUJE ten tekst jako prawdziwy HTML - jesli
// uzytkownik wpisze np. <script>zlosliwyKod()</script>, ten kod
// zostanie FAKTYCZNIE WYKONANY w przegladarce kazdej osoby, ktora
// zobaczy te tresc (atak XSS - Cross-Site Scripting).

const searchInput = document.getElementById("search-input");
searchInput.value = "telefon";
console.log(searchInput.value); // "telefon"

const komentarzUzytkownika = "Super produkt! <script>zly()</script>";
document.getElementById("komentarze").textContent = komentarzUzytkownika;
// textContent wstawia caly string DOSLOWNIE jako tekst - nawet jesli
// zawiera znaczniki <script>, zostana one pokazane jako ZWYKLE ZNAKI
// na stronie, a NIE wykonane jako kod. To calkowicie eliminuje ryzyko
// ataku XSS przy wyswietlaniu danych pochodzacych od uzytkownika.

const input = document.getElementById("search-input");
input.value = "monitor";
console.log(input.value.length);

function escapujHtml(tekst) {
  return tekst.replace(/</g, "&lt;").replace(/>/g, "&gt;");
}

console.log(escapujHtml("<script>zly()</script>"));

function zawieraPotencjalnySkrypt(tekst) {
  return tekst.includes("<script");
}

console.log(zawieraPotencjalnySkrypt("Super produkt!"));
console.log(zawieraPotencjalnySkrypt("Super! <script>zly()</script>"));

// textContent zawsze wstawia caly przekazany string DOSLOWNIE, jako
// zwykly tekst - nigdy nie interpretuje go jako HTML. Jesli string
// zawiera "<b>tekst</b>", na stronie pojawia sie DOKLADNIE ten napis
// (wlacznie ze znakami < i >), a NIE pogrubiony tekst "tekst" - w
// przeciwienstwie do innerHTML, ktore faktycznie zbudowaloby z tego
// znacznik <b> i pogrubilo tresc.

const komentarz = "Super! <img src=x onerror=zly()>";
const kontener = document.getElementById("komentarze");
kontener.textContent = komentarz;

function bezpiecznyTekst(wartosc) {
  return String(wartosc);
}

console.log(bezpiecznyTekst(42));
console.log(bezpiecznyTekst(null));

const input = document.getElementById("search-input");
input.value = "";
console.log(input.value.length);

const staty = document.getElementById("stats");
const przed = staty.textContent;
staty.textContent = "Zaktualizowano";
console.log(przed, staty.textContent);

function zbudujKomunikatHtml(tytul, tresc) {
  return "<strong>" + tytul + "</strong>: " + tresc;
}

console.log(zbudujKomunikatHtml("Uwaga", "dane zaktualizowane"));

// "Zaufany, staly HTML" to tekst, ktory SAM piszesz w kodzie zrodlowym -
// masz nad nim pelna kontrole i wiesz dokladnie, co zawiera (np. szablon
// karty produktu). "Dane od uzytkownika" to tresc, ktorej NIE kontrolujesz -
// uzytkownik moze wpisac cokolwiek, wlacznie ze zlosliwym kodem
// <script>. Dlatego innerHTML jest bezpieczne TYLKO dla tego pierwszego
// przypadku - nigdy dla drugiego.

function czyPoleWypelnione(inputId) {
  return document.getElementById(inputId).value.trim().length > 0;
}

document.getElementById("search-input").value = "  ";
console.log(czyPoleWypelnione("search-input"));

// Zlota zasada: domyslnie uzywaj textContent (bezpieczne w kazdej
// sytuacji), a innerHTML WYLACZNIE dla zaufanego, statycznego HTML,
// ktory sam napisales w kodzie.
//
// element.textContent = komentarzUzytkownika; // ZAWSZE bezpieczne
// element.innerHTML = "<strong>Witaj!</strong>"; // OK, bo TY to napisales

const p1 = document.getElementById("product-1");
const p2 = document.getElementById("product-2");
console.log(p1.textContent === p2.textContent);

function dlugoscTresci(elementId) {
  return document.getElementById(elementId).textContent.length;
}

console.log(dlugoscTresci("stats"));

// innerText MUSI uwzglednic aktualny wyglad strony okreslony przez CSS
// (np. pomija elementy z display:none, bo nie sa "widoczne") - zeby to
// ustalic, przegladarka musi wykonac dodatkowe obliczenia ukladu strony
// (tzw. reflow). textContent NIE uwzglednia CSS w ogole - zwraca caly
// tekst niezaleznie od widocznosci, wiec dziala szybciej.

const input = document.getElementById("search-input");
input.value = "  laptop  ";
console.log(input.value.trim());

function ustawBezpiecznyTekst(elementId, tekst) {
  document.getElementById(elementId).textContent = tekst;
}

ustawBezpiecznyTekst("komentarze", "5 < 10 i 10 > 5");

